"""Post-stop CPU forensic checks and source/capture feasibility review. Never launches native."""
import argparse,collections,json
from pathlib import Path
from contracts import *
from audit_raw import verify_commit_file

def review(run,base,repo):
 plan=read(run/'PLAN.json');ds=read(run/'DONORS.json');conflicts=[]
 for c in plan['cells']:
  actual=ds[c['task']+'|'+c['state']]['KV']
  if actual!=c['mixture_spec']:conflicts.append({'task':c['task'],'recipient':c['recipient'],'state':c['state'],'expected':c['mixture_spec'],'actual_registry':actual})
 require(len(conflicts)==28 and all(c['recipient']=='A' for c in conflicts),'registry collision diagnosis changed')
 led=[json.loads(x) for x in (run/'LEDGER.jsonl').read_text().splitlines()];require(sum(x['event']=='ATTEMPT_STARTED' for x in led)==sum(x['event']=='OWNED_PID' for x in led)==sum(x['event']=='REQUEST_STARTED' for x in led)==1,'unexpected additional native work')
 f0=read(run/'F0.json');pin=next(p for p in f0['bindings'] if p['path'].replace('\\','/').endswith('/native-run/DONORS.json'));require(sha(run/'DONORS.json')==pin['sha256'],'registered flawed registry was changed')
 manifest_pin=verify_commit_file(repo,BASE101,'benchmarks/b570_final_causal_closeout_v1/ARCHIVE_MANIFEST.json',base/'ARCHIVE_MANIFEST.json');manifest={p['path']:p for p in read(base/'ARCHIVE_MANIFEST.json')['files']};freeze=read(base/'F0_BASE.json');source=[]
 for name in ('native/worker.cpp','baseline/source/models/llama.cpp','baseline/source/llama-graph.cpp','baseline/source/llama-kv-cache.cpp','baseline/source/ggml-vulkan.inspected.cpp'):
  pin=manifest.get(name) or next(x for x in freeze['runtime_files'] if x['path']==name);p=base/name;require(sha(p)==pin['sha256'] and p.stat().st_size==pin['bytes'],'source pin changed');source.append(dict(pin,path=str(p)))
 failure_receipt=read(next((run/'receipts').glob('*.json')));require(failure_receipt['status']=='FAILED','failure receipt missing');s=failure_receipt['slot'];record=read(next((run/'records').glob('*.json')));res=Resolver(run,run);x=res.record_file(record['raw_path'],record['raw_sha256']);validate_endpoint(x,s['prompt_ids'],record['owned_pid'],'counts');ev=res.record_file(record['evidence_path'],record['evidence_sha256']);validate_channel(ev,x,s['prompt_ids'],record['owned_pid'],'counts');identity=res.record_file(record['identity_path'],record['identity_sha256']);require(identity['status']=='PASS' and identity['owned_pid']==record['owned_pid'] and not identity['api_layer_loaded'],'failed attempt identity');require(all(any(p['sha256']==m['sha256'] and str(Path(p['path']).resolve()).lower()==str(Path(m['path']).resolve()).lower() for p in f0['bindings']) for m in identity['modules']),'failed attempt loaded runtime differs')
 loaded=json.loads((run/Path(record['identity_path']).parent/'MODULES.stdout').read_text(encoding='utf-8-sig'));require(all(str(Path(p['path']).resolve()).lower() in {str(Path(q).resolve()).lower() for q in loaded} and sha(Path(p['path']))==p['sha256'] for p in f0['driver_module_pins']),'failed attempt actual driver modules')
 req=read(res.resolve(record['raw_path'].replace('.RESULT.json','.REQUEST.json')));actual=ds[s['task']+'|'+s['state']]['KV'];require(req['request_id']==x['request_id'] and req['restore100']['KV']==actual==x['restore100']['KV_source'],'registry/native REQUEST/RESULT different');require(x['restore100']['post_restore_KV_sha256']==actual['sha256']!=s['mixture_spec']['sha256'],'actual wrong KV diagnostic changed');require(x['restore100']['logits_source']==s['initial_logits_spec'] and x['restore100']['post_restore_logits_sha256']==s['initial_logits_spec']['sha256'],'recipient logits changed');require(top2(np.fromfile(s['initial_logits_spec']['path'],dtype='<f4'))[0]==x['ids'][0],'t0 anomaly');life=read(run/Path(record['identity_path']).parent/'LIFECYCLE.json');require(life['pid']==record['owned_pid'] and life['returncode']==0 and life['failed'],'adapter failure lifecycle')
 full=next(c for c in plan['cells'] if c['task']==s['task'] and c['recipient']==s['recipient'] and c['state']=='ALL');require(endpoint(x)==full['reference_endpoint'],'wrong KV does not match raw-pinned full-cross reference')
 failed_attempt_proof={'expected_slot':s['slot'],'pid':record['owned_pid'],'record':record,'requested_state':s['state'],'expected_KV':s['mixture_spec'],'actual_KV':actual,'initial_logits_unchanged':True,'actual_endpoint_matches_historical_full_cross':True,'native_returncode':0,'failure_scope':'adapter detected wrong registered input; native produced a full RESULT; not a qualified EMPTY control','headroom_min_bytes':min(m['device_local_headroom_bytes'] for m in ev['samples']),'target_decode_calls':x['target_decode_calls'],'target_micrographs':x['workload']['target_micrographs'],'sampling_calls':x['workload']['sampling_calls'],'owned_seconds':life['owned_seconds']}
 captures=[];raw_refs=[];no_cache=[]
 for rec in read(base/'STUDY_RECORDS.json'):
  if rec['phase']!='P1C' or rec['observation_mode']!='heavy':continue
  pin=manifest[rec['raw_path']];require(sha(base/rec['raw_path'])==pin['sha256']==rec['raw_sha256'],'projection raw pin');x=read(base/rec['raw_path']);raw_refs.append({'task':rec['task'],'arm':rec['arm'],'repeat':rec['repeat'],'path':rec['raw_path'],'sha256':pin['sha256']})
  no_cache.append(not any(t['op']=='SET_ROWS' or t['dtype']=='f16' for t in x['operator100']['tensors']))
  for t in x['operator100']['tensors']:
   if t['name'] not in ('Vcur-0','Kcur-0'):continue
   pp=t['payload'];p=base/pp['path'];require(p.stat().st_size==pp['bytes'] and sha(p)==pp['sha256']==manifest[pp['path']]['sha256'],'projection payload pin')
   require(t['dtype']=='f32' and t['device']=='Vulkan0','projection dtype/device');captures.append({k:t[k] for k in ('name','op','dtype','ne','nb','view_offset','micrograph_pos','micrograph_width','native_context_ub','tensor_identity','buffer_identity','payload','actual_shader_pipeline','dispatch_dimensions')}|{'task':rec['task'],'arm':rec['arm'],'repeat':rec['repeat'],'raw_path':rec['raw_path']})
 grouped=collections.defaultdict(dict)
 for t in captures:grouped[(t['raw_path'],t['micrograph_pos'],t['name'])][t['op']]=t
 for key,group in grouped.items():
  require('MUL_MAT' in group and 'RESHAPE' in group and group['MUL_MAT']['payload']['sha256']==group['RESHAPE']['payload']['sha256'] and group['MUL_MAT']['buffer_identity']==group['RESHAPE']['buffer_identity'],'projection/reshape capture identity not established')
 return {'cpu_only_created_after_native_stop':True,'integration_failure':{'type':'FROZEN_DONOR_REGISTRY_KEY_COLLISION','key':'task|state omits recipient','registered_KV_keys':sum('KV' in x for x in ds.values()),'required_distinct_KV_entries':len(plan['cells']),'conflicting_cells':conflicts,'conflicting_cells_count':len(conflicts),'new_native_attempts':1,'retry':False,'source_or_frozen_registry_repair_performed':False,'failed_attempt_raw_proof':failed_attempt_proof,'remaining_slots':'NOT_STARTED_CONTROL_GATE_STOP'},'upstream':{'source_pins':source,'manifest_pin':manifest_pin,'raw_records':raw_refs,'projection_captures_verified':len(captures),'captures':captures,'all_operator_raws_lack_f16_cache_write_capture':all(no_cache),'capture_tasks':sorted({r['task'] for r in raw_refs}),'V_projection_reshape_byte_identity_scope':'FP32 MUL_MAT and RESHAPE share corresponding captured payload; layout/source inspection does not prove F16 GPU cache-write lineage','K_has_distinct_post_ROPE_capture':any(t['op']=='ROPE' and t['name']=='Kcur-0' for t in captures),'V_serialized_provenance_match':'NOT_ESTABLISHED','K_serialized_provenance_match':'NOT_ESTABLISHED','reason':'missing actual F16 cache-write intermediate and shader dispatch lineage; same endpoint does not establish original donor byte identity; no host cast substituted as GPU proof','hook_feasibility':'source-level insertion points identified, implementation/alias/synchronization/native qualification pending','hook_executed':False,'natural_reachability':'NOT_ESTABLISHED'}}
if __name__=='__main__':
 ap=argparse.ArgumentParser();ap.add_argument('--run',type=Path,required=True);ap.add_argument('--baseline',type=Path,required=True);ap.add_argument('--repo',type=Path,required=True);ap.add_argument('--output',type=Path,required=True);a=ap.parse_args();r=review(a.run,a.baseline,a.repo);write(a.output,r);print(json.dumps({'registered_KV_collision_cells':r['integration_failure']['conflicting_cells_count'],'new_native_attempts':1,'projection_payloads_verified':r['upstream']['projection_captures_verified'],'cache_provenance':'NOT_ESTABLISHED'}))
